import{_ as s,a,b as t,c as i,d as r,e as o,f as l,g as n,h as p,i as d,j as c,k as m,l as h,m as g,n as u,o as b,p as k,q as f,r as y,s as v,t as j,u as w,v as x,w as C}from"./chunks/16-asteroids.DY9ow4BP.js";import{_ as F,o as _,c as X,a2 as q}from"./chunks/framework.BetZR81g.js";const M=JSON.parse('{"title":"Games and applications","description":"","frontmatter":{"lang":"en","sourcePath":"examples/projects/README.md","next":false},"headers":[],"relativePath":"examples/projects.md","filePath":"examples/projects.md"}'),E={name:"examples/projects.md"};function B(A,e,S,D,T,P){return _(),X("div",null,[...e[0]||(e[0]=[q('<h1 id="games-and-applications" tabindex="-1">Games and applications <a class="header-anchor" href="#games-and-applications" aria-label="Permalink to &quot;Games and applications&quot;">​</a></h1><blockquote><p>Breakout runs in this repository. The other projects are separate repositories or npm packages; use the working directory shown for each one. All require a graphical session and the native build requirements. Their dependency versions are independent of the sfml.js release.</p></blockquote><p><a href="/examples">Overview</a> · <a href="/examples/features">Feature examples</a> · <a href="/examples/official">Official examples</a></p><p><a id="game-projects"></a></p><p><a id="super-mario-kart"></a></p><h2 id="super-mario-kart" tabindex="-1">Süper Mario Kart <a class="header-anchor" href="#super-mario-kart" aria-label="Permalink to &quot;Süper Mario Kart&quot;">​</a></h2><div class="project-feature"><div class="example-gallery project-gallery"><article class="example-entry project-summary-entry" id="super-mario-kart-game"><div class="project-overview"><a class="project-preview" href="/media/examples/projects/super-mario-kart.webp"><img src="'+s+`" width="360" alt="Süper Mario Kart: a played race on Donut Plains 1 in the TypeScript port"><span class="project-preview-label">View full-size screenshot</span></a><div class="example-info"><p class="project-description">A native kart racer in TypeScript and sfml.js, with Mode 7 rendering, drifting, jumps, coins and items.</p><dl class="project-facts"><div><dt>Race</dt><dd>One player against seven AI drivers</dd></div><div><dt>Modes</dt><dd>Grand Prix: five circuits · Versus: one circuit</dd></div><div><dt>Classes</dt><dd>50cc · 100cc · 150cc</dd></div></dl><div class="project-actions"><a class="project-run-link" href="#super-mario-kart-run">Install and run</a><a href="https://github.com/XadillaX/super-mario-kart-sfml.js/tree/HEAD/src">View source</a></div></div></div></article></div><section class="project-run" aria-labelledby="super-mario-kart-run"><h3 id="super-mario-kart-run">Install and run</h3><p>Node.js 20.5+ · Graphical desktop with audio · <a href="/guide/getting-started#requirements">Native build prerequisites</a></p><p>Clone into your projects directory, then run from the game repository:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/XadillaX/super-mario-kart-sfml.js.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> super-mario-kart-sfml.js</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p><code>npm start</code> compiles to <code>dist/</code> and launches the game. Python circuit-authoring tools are optional.</p></section><section class="project-controls" aria-labelledby="super-mario-kart-controls"><h3 id="super-mario-kart-controls">Controls</h3><dl class="project-key-list"><div><dt><kbd>X</kbd></dt><dd>Accelerate</dd></div><div><dt><kbd>Z</kbd></dt><dd>Brake</dd></div><div><dt><kbd>C</kbd></dt><dd>Hop / drift</dd></div><div><dt><kbd>Left</kbd> <kbd>Right</kbd></dt><dd>Steer</dd></div><div><dt><kbd>Up</kbd> <kbd>Down</kbd></dt><dd>Use item forward / backward</dd></div><div><dt><kbd>Enter</kbd></dt><dd>Confirm / skip flyover</dd></div><div><dt><kbd>Esc</kbd></dt><dd>Pause</dd></div></dl><p class="project-hint">To resume, select <strong>No</strong> in the pause menu and press <kbd>Enter</kbd>; <strong>Yes</strong> gives up the race.</p><p class="project-hint">The Controls and Settings menus configure bindings, volume and resolution.</p></section><details class="project-notes"><summary><span>Circuits, source and license</span><span class="project-expand" aria-hidden="true">Expand</span><span class="project-collapse" aria-hidden="true">Collapse</span></summary><div class="project-notes-content"><p><a href="https://github.com/XadillaX/super-mario-kart-sfml.js" target="_blank" rel="noreferrer">super-mario-kart-sfml.js</a> is a <strong>TypeScript + sfml.js</strong> port of <a href="https://github.com/vmbatlle/super-mario-kart" target="_blank" rel="noreferrer">vmbatlle/super-mario-kart</a>, originally written in C++ with SFML 2.5.1. Its 54 TypeScript modules follow the upstream source layout, retaining Mode 7 rendering, gameplay, AI and assets.</p><p>Pinned dependencies: <code>sfml.js@1.0.0-rc.2</code> and <code>typescript@7.0.2</code>.</p><p>The circuits are Donut Plains 1, Mario Circuit 2, Ghost Valley 1, Bowser Castle 1 and Rainbow Road. Code is licensed under <a href="https://github.com/XadillaX/super-mario-kart-sfml.js/blob/HEAD/LICENSE" target="_blank" rel="noreferrer">GPL v3</a>; the characters, graphics and music belong to Nintendo. This is an unofficial educational fan project.</p></div></details></div><p><a id="play-nes"></a></p><h2 id="play-nes" tabindex="-1">play-nes <a class="header-anchor" href="#play-nes" aria-label="Permalink to &quot;play-nes&quot;">​</a></h2><div class="project-feature"><div class="example-gallery project-gallery"><article class="example-entry project-summary-entry" id="play-nes-player"><div class="project-overview"><a class="project-preview" href="/media/examples/projects/play-nes.webp"><img src="`+a+`" width="360" alt="play-nes: Concentration Room"><span class="project-preview-label">View full-size screenshot</span></a><div class="example-info"><p class="project-description">A TypeScript desktop NES emulator. JSNES emulates the console; sfml.js provides native graphics and audio.</p><dl class="project-facts"><div><dt>Preview</dt><dd>Concentration Room, included with the player</dd></div><div><dt>Games</dt><dd>Bundled game or a local ROM you have permission to use</dd></div><div><dt>Input</dt><dd>Keyboard mappings for two players</dd></div></dl><div class="project-actions"><a class="project-run-link" href="#play-nes-run">Install and run</a><a href="https://github.com/XadillaX/play-nes">View source</a></div></div></div></article></div><section class="project-run" aria-labelledby="play-nes-run"><h3 id="play-nes-run">Install and run</h3><p>Node.js 22 recommended · Python and a C++20 compiler · Graphical desktop with audio</p><p>Install the published player and launch the bundled game:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> play-nes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nes</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> croom</span></span></code></pre></div><p>To open a local ROM you have permission to use:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nes</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/path/to/your game.nes&quot;</span></span></code></pre></div></section><section class="project-controls" aria-labelledby="play-nes-controls"><h3 id="play-nes-controls">Controls</h3><div class="project-players"><div><h4>Player 1</h4><dl class="project-player-keys"><div><dt>Directions</dt><dd><kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd></dd></div><div><dt>A / B</dt><dd><kbd>J</kbd> <kbd>K</kbd></dd></div><div><dt>Select</dt><dd><kbd>Right Shift</kbd></dd></div><div><dt>Start</dt><dd><kbd>Enter</kbd></dd></div></dl></div><div><h4>Player 2</h4><dl class="project-player-keys"><div><dt>Directions</dt><dd><kbd>Left</kbd> <kbd>Right</kbd> <kbd>Up</kbd> <kbd>Down</kbd></dd></div><div><dt>A / B</dt><dd><kbd>Numpad 5</kbd> <kbd>Numpad 6</kbd></dd></div><div><dt>Select</dt><dd><kbd>Numpad 8</kbd></dd></div><div><dt>Start</dt><dd><kbd>Numpad 9</kbd></dd></div></dl></div></div><p class="project-hint"><kbd>Esc</kbd> or window close exits. Held buttons are released on focus loss.</p></section><details class="project-notes"><summary><span>Display and speed options</span><span class="project-expand" aria-hidden="true">Expand</span><span class="project-collapse" aria-hidden="true">Collapse</span></summary><div class="project-notes-content"><p><code>--scale 3</code> changes window scale; <code>--frameRate 60</code> selects normal speed. Frame rate changes emulation speed, not only display speed. Use <code>nes --help</code> for all options.</p></div></details></div><p><a id="breakout"></a></p><h2 id="play-breakout" tabindex="-1">Play Breakout <a class="header-anchor" href="#play-breakout" aria-label="Permalink to &quot;Play Breakout&quot;">​</a></h2><p>From the sfml.js repository root, run <code>npm ci</code> once, then <code>node examples/breakout.cjs</code>. Run <code>npm run build</code> after source changes.</p><div class="example-gallery project-gallery"><article class="example-entry" id="breakout-game"><a href="/media/breakout.png"><img src="`+t+`" width="360" alt="Breakout rendered in a native window"></a><div class="example-info"><p><a href="https://github.com/XadillaX/node-sfml/blob/main/examples/breakout.cjs">breakout.cjs</a> is a complete game with brick collisions, three lives, scoring and win/loss states. Move with Left/Right or A/D; Space launches or restarts, P pauses, and Esc exits. Losing focus pauses interactive play.</p></div></article></div><p>Use <code>npm run demo:breakout</code> to build and launch. For a reproducible gameplay capture on macOS/Linux:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SFML_DEMO_SNAPSHOT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/tmp/sfml-breakout.png</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/breakout.cjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --autoplay</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frames=1500</span></span></code></pre></div><p>The screenshot saves the actual native framebuffer at the final frame. <code>--autoplay</code> controls the paddle; <code>--frames</code> bounds the run. <code>node examples/breakout.cjs --self-test</code> checks the game logic without opening a window.</p><p><a id="node-sfml-demos"></a></p><h2 id="node-sfml-demos" tabindex="-1">node-sfml-demos <a class="header-anchor" href="#node-sfml-demos" aria-label="Permalink to &quot;node-sfml-demos&quot;">​</a></h2><p><a href="https://github.com/XadillaX/node-sfml-demos" target="_blank" rel="noreferrer">node-sfml-demos</a> contains Bomberman, Breakout, Tetris, Doodle Jump and Arkanoid implementations using sfml.js.</p><p>Clone this separate repository into your projects directory, then install dependencies and launch from the game&#39;s own directory. For Bomberman:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/XadillaX/node-sfml-demos.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node-sfml-demos/bomberman</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> index.js</span></span></code></pre></div><p>See the <a href="https://github.com/XadillaX/node-sfml-demos#readme" target="_blank" rel="noreferrer">repository README</a> for game directories, controls and upstream C++ sources. The <a href="/guide/getting-started#requirements">native build requirements</a> also apply.</p><p>Use Node.js 22, Python 3 and a C++20 toolchain. Install inside each game folder with <code>npm install</code>, then run <code>node index.js</code> there. Keep the full repository because some games share fonts and textures. Each game pins <code>sfml.js@1.0.0-rc.2</code>; this page does not upgrade it. All support the close button; Bomberman also uses audio. Tetris, Doodle Jump and Arkanoid retain the prototypes&#39; incomplete gameplay.</p><div class="example-gallery project-gallery"><article class="example-entry" id="demo-bomberman"><a href="/media/examples/projects/node-sfml-demos/bomberman.webp"><img src="`+i+'" width="360" alt="Bomberman: Two-player Bomberman in a tiled arena."></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml-demos/tree/HEAD/bomberman">Bomberman</a></strong></p><p>Two-player Bomberman in a tiled arena.</p><p><strong>Controls</strong> · Player 1: WASD and Left Ctrl for bombs. Player 2: arrows and Space for bombs. Mouse operates the menu; Esc pauses/resumes.</p><p>Run inside: <code>node-sfml-demos/bomberman/</code></p><p><code>npm install</code><br><code>node index.js</code></p><p><a href="https://github.com/PiGames/Bomberman">Original C++ source</a></p></div></article><article class="example-entry" id="demo-breakout"><a href="/media/examples/projects/node-sfml-demos/breakout.webp"><img src="'+r+'" width="360" alt="Breakout: A brick breaker against a starry backdrop."></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml-demos/tree/HEAD/breakout">Breakout</a></strong></p><p>A brick breaker against a starry backdrop.</p><p><strong>Controls</strong> · A/D or Left/Right moves and launches; Space also launches. Release Space after losing to reset. Esc exits.</p><p>Run inside: <code>node-sfml-demos/breakout/</code></p><p><code>npm install</code><br><code>node index.js</code></p></div></article><article class="example-entry" id="demo-tetris"><a href="/media/examples/projects/node-sfml-demos/tetris.webp"><img src="'+o+'" width="360" alt="Tetris: Falling blocks inside a gold frame."></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml-demos/tree/HEAD/tetris">Tetris</a></strong></p><p>Falling blocks inside a gold frame.</p><p><strong>Controls</strong> · Left/Right moves, Up rotates, Down drops faster.</p><p>Run inside: <code>node-sfml-demos/tetris/</code></p><p><code>npm install</code><br><code>node index.js</code></p><p><a href="https://github.com/jsyqrt/games/blob/master/01%20Tetris/main.cpp">Original C++ source</a></p></div></article><article class="example-entry" id="demo-doodle-jump"><a href="/media/examples/projects/node-sfml-demos/doodle-jump.webp"><img src="'+l+'" width="360" alt="Doodle Jump: Jump between green platforms."></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml-demos/tree/HEAD/doodle_jump">Doodle Jump</a></strong></p><p>Jump between green platforms.</p><p><strong>Controls</strong> · Left/Right moves; jumping is automatic.</p><p>Run inside: <code>node-sfml-demos/doodle_jump/</code></p><p><code>npm install</code><br><code>node index.js</code></p><p><a href="https://github.com/jsyqrt/games/blob/master/02%20Doodle%20Jump/main.cpp">Original C++ source</a></p></div></article><article class="example-entry" id="demo-arkanoid"><a href="/media/examples/projects/node-sfml-demos/arkanoid.webp"><img src="'+n+`" width="360" alt="Arkanoid: A compact brick breaker with green bricks."></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml-demos/tree/HEAD/arkanoid">Arkanoid</a></strong></p><p>A compact brick breaker with green bricks.</p><p><strong>Controls</strong> · Left/Right moves the paddle; the ball starts automatically.</p><p>Run inside: <code>node-sfml-demos/arkanoid/</code></p><p><code>npm install</code><br><code>node index.js</code></p><p><a href="https://github.com/jsyqrt/games/blob/master/03%20Arkanoid/main.cpp">Original C++ source</a></p></div></article></div><p><a id="16-games"></a></p><h2 id="_16-games-in-clojurescript" tabindex="-1">16 games in ClojureScript <a class="header-anchor" href="#_16-games-in-clojurescript" aria-label="Permalink to &quot;16 games in ClojureScript&quot;">​</a></h2><p><a href="https://github.com/XadillaX/16-sfml.js-games-ported" target="_blank" rel="noreferrer">16-sfml.js-games-ported</a> is a fork of <a href="https://github.com/jsyqrt/games" target="_blank" rel="noreferrer">jsyqrt/games</a>. The original 16 games were written in <strong>C++ with SFML</strong>; this fork ports all of them to <strong>ClojureScript with sfml.js</strong>, preserving the original directory layout, assets, game logic and controls.</p><p>The games run on Node.js through <strong>nbb</strong>, with no JVM or separate compilation step. Clone the game repository into your projects directory, then run from its root:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/XadillaX/16-sfml.js-games-ported.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 16-sfml.js-games-ported</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nbb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;01 Tetris/main.cljs&quot;</span></span></code></pre></div><p>Requires Node.js 20.5+ and the <a href="/guide/getting-started#requirements">native build requirements</a>, plus a graphical session with OpenGL window support. Dependencies are pinned to <code>sfml.js@1.0.0-rc.2</code> and <code>nbb@1.6.214</code>. Each script resolves its assets relative to its own directory.</p><div class="example-gallery project-gallery"><article class="example-entry" id="01-tetris"><a href="/media/examples/projects/16-games/01-tetris.webp"><img src="`+p+'" width="360" alt="Tetris playing field with a falling purple block"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/16-sfml.js-games-ported/blob/HEAD/01%20Tetris/main.cljs">01 · Tetris</a></strong></p><p>Falling blocks and line clearing</p><p><strong>Controls</strong> · Left/Right moves, Up rotates, Down drops faster</p><p><code>npx nbb &quot;01 Tetris/main.cljs&quot;</code></p></div></article><article class="example-entry" id="02-doodle-jump"><a href="/media/examples/projects/16-games/02-doodle-jump.webp"><img src="'+d+'" width="360" alt="Doodle Jump character above green platforms on graph paper"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/16-sfml.js-games-ported/blob/HEAD/02%20Doodle%20Jump/main.cljs">02 · Doodle Jump</a></strong></p><p>Jump between platforms as the screen scrolls</p><p><strong>Controls</strong> · Left/Right moves; jumping is automatic</p><p><code>npx nbb &quot;02 Doodle Jump/main.cljs&quot;</code></p></div></article><article class="example-entry" id="03-arkanoid"><a href="/media/examples/projects/16-games/03-arkanoid.webp"><img src="'+c+'" width="360" alt="Arkanoid green brick wall and paddle"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/16-sfml.js-games-ported/blob/HEAD/03%20Arkanoid/main.cljs">03 · Arkanoid</a></strong></p><p>Break bricks with a bouncing ball</p><p><strong>Controls</strong> · Left/Right moves the paddle</p><p><code>npx nbb &quot;03 Arkanoid/main.cljs&quot;</code></p></div></article><article class="example-entry" id="04-snake"><a href="/media/examples/projects/16-games/04-snake.webp"><img src="'+m+'" width="360" alt="Snake and food on a square grid"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/16-sfml.js-games-ported/blob/HEAD/04%20Snake/main.cljs">04 · Snake</a></strong></p><p>Collect food and grow</p><p><strong>Controls</strong> · arrow keys change direction</p><p><code>npx nbb &quot;04 Snake/main.cljs&quot;</code></p></div></article><article class="example-entry" id="05-minesweeper"><a href="/media/examples/projects/16-games/05-minesweeper.webp"><img src="'+h+'" width="360" alt="Minesweeper board with covered cells"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/16-sfml.js-games-ported/blob/HEAD/05%20Minesweeper/main.cljs">05 · Minesweeper</a></strong></p><p>Reveal cells and mark hidden mines</p><p><strong>Controls</strong> · left-click reveals, right-click flags</p><p><code>npx nbb &quot;05 Minesweeper/main.cljs&quot;</code></p></div></article><article class="example-entry" id="06-fifteen-puzzle"><a href="/media/examples/projects/16-games/06-fifteen-puzzle.webp"><img src="'+g+'" width="360" alt="Numbered fifteen-puzzle tiles with one empty square"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/16-sfml.js-games-ported/blob/HEAD/06%20Fifteen-Puzzle/main.cljs">06 · Fifteen-Puzzle</a></strong></p><p>A 4 × 4 sliding-tile puzzle</p><p><strong>Controls</strong> · click a tile next to the empty square to slide it</p><p><code>npx nbb &quot;06 Fifteen-Puzzle/main.cljs&quot;</code></p></div></article><article class="example-entry" id="07-racing-top-down"><a href="/media/examples/projects/16-games/07-racing-top-down.webp"><img src="'+u+'" width="360" alt="Colored cars on the top-down racing track"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/16-sfml.js-games-ported/blob/HEAD/07%20Racing%20%28Top%20Down%29/main.cljs">07 · Racing (Top Down)</a></strong></p><p>Race alongside computer-controlled cars</p><p><strong>Controls</strong> · Up accelerates, Down brakes/reverses, Left/Right steers</p><p><code>npx nbb &quot;07 Racing (Top Down)/main.cljs&quot;</code></p></div></article><article class="example-entry" id="08-outrun"><a href="/media/examples/projects/16-games/08-outrun.webp"><img src="'+b+'" width="360" alt="Outrun road receding toward hills with roadside trees"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/16-sfml.js-games-ported/blob/HEAD/08%20Outrun/main.cljs">08 · Outrun</a></strong></p><p>Perspective road, curves and roadside scenery</p><p><strong>Controls</strong> · Left/Right steers, Up/Down moves forward/backward, Tab boosts speed, W/S changes camera height</p><p><code>npx nbb &quot;08 Outrun/main.cljs&quot;</code></p></div></article><article class="example-entry" id="09-xonix"><a href="/media/examples/projects/16-games/09-xonix.webp"><img src="'+k+'" width="360" alt="Xonix enemies inside the blue-bordered playing field"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/16-sfml.js-games-ported/blob/HEAD/09%20Xonix/main.cljs">09 · Xonix</a></strong></p><p>Capture territory while avoiding enemies</p><p><strong>Controls</strong> · arrow keys move, Esc resets the board</p><p><code>npx nbb &quot;09 Xonix/main.cljs&quot;</code></p></div></article><article class="example-entry" id="10-bejeweled"><a href="/media/examples/projects/16-games/10-bejeweled.webp"><img src="'+f+'" width="360" alt="Bejeweled board filled with colored gems"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/16-sfml.js-games-ported/blob/HEAD/10%20Bejeweled/main.cljs">10 · Bejeweled</a></strong></p><p>Swap neighboring gems to form matching lines</p><p><strong>Controls</strong> · click two adjacent gems to swap</p><p><code>npx nbb &quot;10 Bejeweled/main.cljs&quot;</code></p></div></article><article class="example-entry" id="11-netwalk"><a href="/media/examples/projects/16-games/11-netwalk.webp"><img src="'+y+'" width="360" alt="NetWalk pipe network with computers and a server"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/16-sfml.js-games-ported/blob/HEAD/11%20NetWalk%20%28Pipe%20Puzzle%29/main.cljs">11 · NetWalk (Pipe Puzzle)</a></strong></p><p>Connect the computers to the server</p><p><strong>Controls</strong> · click a pipe to rotate it</p><p><code>npx nbb &quot;11 NetWalk (Pipe Puzzle)/main.cljs&quot;</code></p></div></article><article class="example-entry" id="12-mahjong-solitaire"><a href="/media/examples/projects/16-games/12-mahjong-solitaire.webp"><img src="'+v+'" width="360" alt="Layered Mahjong Solitaire tiles on a wooden table"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/16-sfml.js-games-ported/blob/HEAD/12%20Mahjong%20Solitaire/main.cljs">12 · Mahjong Solitaire</a></strong></p><p>Remove matching pairs of available tiles</p><p><strong>Controls</strong> · left-click selects pairs, right-click undoes</p><p><code>npx nbb &quot;12 Mahjong Solitaire/main.cljs&quot;</code></p></div></article><article class="example-entry" id="13-tron"><a href="/media/examples/projects/16-games/13-tron.webp"><img src="'+j+'" width="360" alt="Red and green players on the dark Tron grid"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/16-sfml.js-games-ported/blob/HEAD/13%20Tron/main.cljs">13 · Tron</a></strong></p><p>Two-player light-cycle trails</p><p><strong>Controls</strong> · arrow keys for red, W/A/S/D for green</p><p><code>npx nbb &quot;13 Tron/main.cljs&quot;</code></p></div></article><article class="example-entry" id="14-chess"><a href="/media/examples/projects/16-games/14-chess.webp"><img src="'+w+'" width="360" alt="Chess board and pieces"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/16-sfml.js-games-ported/blob/HEAD/14%20Chess/main.cljs">14 · Chess</a></strong></p><p>Draggable board with an external Stockfish engine</p><p><strong>Controls</strong> · drag pieces, Space requests an engine move, Backspace undoes</p><p><code>npx nbb &quot;14 Chess/main.cljs&quot; /path/to/stockfish</code></p><p>Install an external <a href="https://github.com/official-stockfish/Stockfish/releases">Stockfish executable</a> for your OS and pass its extracted executable path. The engine is not bundled. On Windows, placing stockfish.exe beside main.cljs also works without an argument.</p></div></article><article class="example-entry" id="15-volleyball"><a href="/media/examples/projects/16-games/15-volleyball.webp"><img src="'+x+'" width="360" alt="Red and green volleyball players beside a beach net"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/16-sfml.js-games-ported/blob/HEAD/15%20Volleyball/main.cljs">15 · Volleyball</a></strong></p><p>Two-player volleyball with Box2D physics</p><p><strong>Controls</strong> · Left/Right and Up for red; A/D and W for green; Up/W jumps</p><p><code>npx nbb &quot;15 Volleyball/main.cljs&quot;</code></p><p><code>box2dweb@2.1.0-b</code> is installed by the game repository&#39;s root <code>npm ci</code>.</p></div></article><article class="example-entry" id="16-asteroids"><a href="/media/examples/projects/16-games/16-asteroids.webp"><img src="'+C+'" width="360" alt="Asteroids against a star-filled background"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/16-sfml.js-games-ported/blob/HEAD/16%20Asteroids/main.cljs">16 · Asteroids</a></strong></p><p>Pilot a spaceship and break apart asteroids</p><p><strong>Controls</strong> · Left/Right rotates, Up thrusts, Space fires</p><p><code>npx nbb &quot;16 Asteroids/main.cljs&quot;</code></p></div></article></div><p>Chess requires an external <a href="https://github.com/official-stockfish/Stockfish/releases" target="_blank" rel="noreferrer">Stockfish executable</a> for your operating system; pass its path as shown above. Volleyball uses <code>box2dweb</code>, installed by <code>npm ci</code>. Close the game window to exit. See the <a href="https://github.com/XadillaX/16-sfml.js-games-ported#games" target="_blank" rel="noreferrer">game gallery</a> for screenshots, source files and controls.</p><h2 id="screenshot-sources" tabindex="-1">Screenshot sources <a class="header-anchor" href="#screenshot-sources" aria-label="Permalink to &quot;Screenshot sources&quot;">​</a></h2><p>Game assets come from the credited upstream projects. <a href="/media/examples/projects/provenance.json">provenance.json</a> records screenshot sources and processing. A screenshot is not a compatibility or gameplay test report. Original game assets retain their authors&#39; rights; these previews do not relicense them.</p><p>The C++ originals and tutorials are credited by <a href="https://github.com/jsyqrt/games" target="_blank" rel="noreferrer">jsyqrt/games</a>; the reference migration is <a href="https://github.com/XadillaX/16-sfml.js-games-ported#sources" target="_blank" rel="noreferrer">XadillaX/16-sfml.js-games-ported</a>. <a href="https://github.com/XadillaX/node-sfml-demos#license" target="_blank" rel="noreferrer">node-sfml-demos</a> and <a href="https://github.com/XadillaX/play-nes#readme" target="_blank" rel="noreferrer">play-nes</a> document their own licenses and credits.</p>',36)])])}const L=F(E,[["render",B]]);export{M as __pageData,L as default};
